pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: two distinct actors
    function testFuzz_property(address actor1, address actor2) public {
        // keep addresses in the wide admissible domain and distinct
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != actor2);

        // actor1 must be a contract that returns the proper supportsToken() value
        // We deploy a small helper and then impersonate it when calling airDrop via msg.sender
        // but airDrop expects Bank(msg.sender).supportsToken() to equal keccak256("Nu Token")
        // We'll deploy a simple helper and then prank from its address.

        // Deploy a helper that matches Bank
        BankLike helper1 = new BankLike();
        BankLike helper2 = new BankLike();

        // Ensure helpers have non-zero addresses (they do) and map to actor1/actor2 fuzzing by using prank to those helper addresses
        // First call: from helper1, call airDrop - should succeed and give helper1 balance +20
        vm.prank(address(helper1));
        try c.airDrop() {
            // ignore
        } catch {
            // if it reverts on reference implementation something is wrong, but keep going
        }

        // Second call: from helper2, call airDrop - on reference this should succeed and give helper2 balance +20
        bool ok;
        vm.prank(address(helper2));
        try c.airDrop() { ok = true; } catch { ok = false; }

        // The universal property to assert: on the correct contract, a second distinct caller can still perform airDrop (ok == true)
        // The mutant that leaves _locked = true after first call will make ok == false for some inputs (here helper2)
        assertTrue(ok);
    }
}

// Minimal helper matching Bank interface
contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address `caller` and an arbitrary other address `k`.
    // The general rule we test: after caller calls airDrop, only tokenBalance(caller) may change.
    // We assert that tokenBalance(k) == 0 (unchanged) for all inputs when k != caller.
    function testFuzz_property(address caller, address k) public {
        // keep addresses distinct and non-zero to avoid degenerate trivial cases
        vm.assume(caller != address(0));
        vm.assume(k != address(0));

        // Ensure the external supportsToken check succeeds: Bank supportsToken must be at msg.sender.
        // The contract expects msg.sender to be a Bank that returns keccak256("Nu Token").
        // We deploy a minimal Bank helper that returns the required value and then prank as that Bank.
        BankHelper bank = new BankHelper();

        // Ensure tokenBalance(k) initially 0 (reference enforces hasNoBalance on caller, but other keys should be 0)
        uint before_k = c.tokenBalance(k);

        // Make the call come from the BankHelper but with tx.origin simulated as caller via prank
        // The supportsToken modifier checks Bank(msg.sender).supportsToken(), so msg.sender must be bank.
        // We simulate the caller as tx.origin by using vm.prank(caller) together with a call from bank to c.
        // To achieve msg.sender == bank and effect originating from caller, bank will call c.airDrop()

        // Fund bank so it can call (no ETH needed, but keep wide domain)
        vm.deal(address(bank), 1 ether);

        // Instruct bank to call airDrop on c with tx.origin = caller
        vm.prank(caller);
        bank.callAirDrop(address(c));

        // After the call, read tokenBalance(k)
        uint after_k = c.tokenBalance(k);

        // The reference guarantees that a call to airDrop can only change the caller's balance (i.e., at key == caller).
        // Therefore for any k != caller, tokenBalance(k) must remain equal to its prior value (here expected 0).
        // This single assert reads c's public getter; the buggy mutant (without hasNoBalance) will allow some sequences
        // where balances at other keys differ, causing this assertion to fail for some fuzz inputs.
        assertTrue(after_k == before_k);
    }
}

// Minimal helper that acts like Bank and calls C.airDrop with msg.sender == address(this)
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Allow being called with prank such that tx.origin is the fuzzed caller.
    function callAirDrop(address c) external {
        C(c).airDrop();
    }
}

