pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (who invokes airDrop) and some other address k to observe.
    // We keep domain wide: any two addresses. We will ensure caller is funded so calls succeed if needed.
    function testFuzz_property(address caller, address k) public {
        // avoid the trivial case where both addresses are zero address for clarity
        vm.assume(caller != address(0));
        vm.assume(k != address(0));

        // Ensure caller has ETH to make any external calls (not strictly necessary here, but safe)
        vm.deal(caller, 1 ether);

        // Record pre-state balances at key k
        uint pre = c.tokenBalance(k);

        // Make the call as `caller` to airDrop
        vm.prank(caller);
        // call and ignore revert (airDrop shouldn't revert in reference for admissible inputs)
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // Record post-state balances at key k
        uint post = c.tokenBalance(k);

        // General rule (single assertion): For the reference C, for ANY caller and ANY observed key k,
        // a call to airDrop never changes tokenBalance(k) for keys that are not the caller (i.e., tokenBalance(k)
        // is unchanged unless k == caller). Thus if k != caller, pre == post must hold in the reference.
        // The mutant removing hasNoBalance can violate this for some caller,k, so this assertion will fail on the mutant.
        if (k != caller) {
            assertTrue(pre == post);
        } else {
            // when k == caller the reference may increase caller's own balance by 20 only if prior balance==0
            // but we must still assert something that holds for all inputs on the reference. The following is such:
            // The reference will never decrease tokenBalance(caller) as airDrop only adds 20, so post >= pre.
            assertTrue(post >= pre);
        }
    }
}

