pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address (actor) to find one that exercises the difference
    function testFuzz_property(address actor) public {
        // keep actor non-zero to be a realistic caller
        vm.assume(actor != address(0));

        // Ensure actor starts with zero balance in tokenBalance
        // Since tokenBalance is public mapping default is 0; we just call as actor
        // We must call airDrop from a Bank contract context: the contract code expects Bank(msg.sender).supportsToken()
        // Build a minimal legitimate Bank that returns the expected keccak256("Nu Token")
        BankLegit bank = new BankLegit();

        // Have the fuzzed EOA address be the address that calls airDrop by using vm.prank
        // But C.supportsToken uses Bank(msg.sender).supportsToken(), so msg.sender must be the Bank address.
        // Therefore we need to have the Bank call c.airDrop() on behalf of the actor. We deploy a caller helper that acts as the Bank
        // and forwards an external tx to c.airDrop using the privileged actor as the externally-controlled origin.

        // Deploy a forwarder that will call c.airDrop() when instructed by the fuzzed actor.
        CallerAsBank caller = new CallerAsBank(c);

        // The deployed CallerAsBank implements supportsToken and thus is seen as Bank by C.
        // We need the callee to treat CallerAsBank as the caller, but we also want the EOA 'actor' to be the origin of this operation
        // to simulate different senders: We'll have actor call the caller contract which in turn calls c.airDrop().

        // Fund actor so it can call (not strictly necessary but safe)
        vm.deal(actor, 1 ether);

        // Actor must have zero tokenBalance initially (mapping default 0). To ensure hasNoBalance holds, we assume mapper is zero.
        assertEq(c.tokenBalance(actor), 0);

        // Now have the actor invoke the caller which will call c.airDrop()
        vm.prank(actor);
        caller.callAirDrop();

        // After the call, in the reference implementation, the caller contract (CallerAsBank) was msg.sender for c.airDrop
        // and tokenBalance[msg.sender] refers to tokenBalance[address(caller)]. Since hasNoBalance required 0 and initial was 0,
        // the reference will increase tokenBalance[address(caller)] by 20. The mutant (comparing to "Fake Token") will cause supportsToken to fail
        // and airDrop will revert, leaving tokenBalance[address(caller)] unchanged at 0. Thus the universal property we check:
        // tokenBalance of the caller contract is either 20 (reference) or 0 (mutant for some inputs). We assert the universal property that
        // the reference sets it to 20 for any actor; the mutant will fail for some actor because of the wrong string.

        // Exactly one assertion reading c's public surface as required:
        assertTrue(c.tokenBalance(address(caller)) == 20);
    }
}

// Minimal helper that will act as the Bank (msg.sender for C) and expose supportsToken matching the reference
contract CallerAsBank {
    C public c;
    constructor(C _c) { c = _c; }
    // act as Bank: return keccak256("Nu Token") so supportsToken() matches reference
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    // called by fuzzed EOA; forwards to c.airDrop
    function callAirDrop() external {
        c.airDrop();
    }
}

// A separate BankLegit is not strictly necessary but included to show legitimate Bank behaviour if needed
contract BankLegit {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

