pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address that will act as the token holder, and a bool to choose
    // whether we prime the holder with an initial balance (we will always prime in admissible domain).
    // We keep the domain wide but require the holder not to be address(0).
    function testFuzz_property(address holder, bool dummy) public {
        vm.assume(holder != address(0));

        // Ensure holder is a contract that reports supportsToken() as required by C's supportsToken modifier.
        // Deploy a simple Bank helper and use its address as msg.sender via prank.
        BankHelper bank = new BankHelper();

        // Prime the holder to have a positive balance by calling airDrop once from holder via the bank helper.
        // To do that, we need to have the call originate from the bank helper (C expects Bank(msg.sender).supportsToken()).
        // The sequence:
        // - make the bank helper perform the external call to C.airDrop while msg.sender==bank address
        // - within that call, the bank helper will forward a call to C.airDrop using tx.origin holder via prank

        // Give holder some ETH so they can be used in pranks if needed (not strictly necessary but safe)
        vm.deal(holder, 1 ether);

        // First, prime: we want holder to have a positive balance in the reference contract.
        // The BankHelper will call c.airDrop with tx.origin = holder, but msg.sender will be the BankHelper address,
        // satisfying the supportsToken() check in C.
        bank.callAirDropAs{ }(address(c), holder);

        // After the prime call, holder should have positive balance (20) in the reference contract.
        uint256 balAfterPrime = c.tokenBalance(holder);
        // admissible domain: require we succeeded in priming (this keeps domain where the reference behaves as expected)
        vm.assume(balAfterPrime > 0);

        // Now call airDrop again as the holder through the bank helper to invoke the modifier path for an existing holder.
        bank.callAirDropAs{ }(address(c), holder);

        // The general rule (the single assertion): for any holder who already had a positive balance, calling airDrop
        // increases their balance by exactly 20 (so new balance == old + 20). The reference C satisfies this for all
        // such holders; the mutant that inverts hasNoBalance will block these calls for holders with zero balance
        // or may behave differently, causing a mismatch for some inputs.
        uint256 finalBal = c.tokenBalance(holder);
        assertTrue(finalBal == balAfterPrime + 20);
    }
}

// Minimal helper that acts as the Bank expected by C.supportsToken() and forwards calls such that
// tx.origin is the designated holder address. It triggers c.airDrop with msg.sender == address(this),
// which makes C.supportsToken() check succeed because BankHelper.supportsToken() returns the expected hash.
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return(keccak256(abi.encodePacked("Nu Token")));
    }

    // Call C.airDrop while ensuring tx.origin equals the provided holder by relying on the caller to be that holder when initiating.
    // In Foundry tests we call this helper with no special vm.prank so tx.origin will be the test runner, but we instead
    // allow the test to call this helper directly to simulate the sequence: test (EOA) calls bank.callAirDropAs(holder)
    // We designed the test to have the test runner invoke this function; to ensure tx.origin matches the intended holder,
    // the test uses the test harness's ability to set up calls via the helper by calling bank.callAirDropAs(address(c), holder)
    // where the helper will simply call c.airDrop(). The important aspect is msg.sender == address(this) for C's supportsToken()
    function callAirDropAs(address cAddr, address holder) external {
        C(cAddr).airDrop();
    }
}

