    // making tokenBalance != 20 after two calls. We fuzz the caller address so fuzzer
    // can find an address with code (we deploy a helper and use its address below).
    function testFuzz_property(address callerSeed) public {
        // Keep domain wide but avoid the zero address
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed)))));
        vm.assume(caller != address(0));

        // Deploy a helper Bank-like contract that supports the token and then will be used as msg.sender
        // Note: C.supportsToken() expects Bank(msg.sender).supportsToken() so we need the caller to be a contract
        BankHelper helper = new BankHelper();

        // Fund the helper so it can call c (EOA-like behaviour not needed, it's a contract)
        vm.deal(address(helper), 1 ether);

        // First call: helper calls c.airDrop() -> should succeed and set tokenBalance(helper) == 20
        bool ok;
        try helper.callAirDrop(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }
