        assertTrue(ok, "first airdrop must succeed");
        assertTrue(c.tokenBalance(address(helper)) == 20, "after first airdrop balance should be 20");

        // Second call immediately from same helper: in reference contract this must not be allowed
        // because hasNoBalance requires tokenBalance[msg.sender] == 0 prior to the call.
